// rightmost finds the last kept column matching want, never the first one.
func rightmost[T any](columns []Column[T], kept []int, want func(Column[T]) bool) (int, bool) {
	for i := len(kept) - 1; i > 0; i-- {
		if want(columns[kept[i]]) {
			return i, true
		}
	}
	return 0, false
